#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void maxpool1d_fp16_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    int batch,
    int channels,
    int length,
    int kernel,
    int stride,
    int padding,
    int dilation,
    int out_length)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * channels * out_length;
    if (idx >= total) return;

    int out_idx   = idx % out_length;
    int tmp       = idx / out_length;
    int channel   = tmp % channels;
    int batch_idx = tmp / channels;

    const __half* in_batch = input + batch_idx * channels * length;
    const __half* in_chan  = in_batch + channel * length;

    __half max_val = __float2half(0.0f);   // zero padding value

    #pragma unroll
    for (int k = 0; k < kernel; ++k) {
        int in_pos = out_idx * stride + k * dilation - padding;
        __half val = __float2half(0.0f);
        if (in_pos >= 0 && in_pos < length) {
            val = in_chan[in_pos];
        }
        max_val = __hgt(val, max_val) ? val : max_val;
    }

    output[idx] = max_val;
}

torch::Tensor maxpool1d_fp16(torch::Tensor input,
                             int kernel,
                             int stride,
                             int padding,
                             int dilation)
{
    // input shape: (B, C, L), dtype = half
    const int batch   = input.size(0);
    const int channels= input.size(1);
    const int length  = input.size(2);

    const int out_length = static_cast<int>(floorf(
        (static_cast<float>(length + 2 * padding - dilation * (kernel - 1) - 1)) / stride + 1));

    auto options = torch::TensorOptions()
                       .dtype(torch::kFloat16)
                       .device(input.device());

    torch::Tensor output = torch::empty({batch, channels, out_length}, options);

    const int threads = 256;
    const int total   = batch * channels * out_length;
    const int blocks  = (total + threads - 1) / threads;

    maxpool1d_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        batch,
        channels,
        length,
        kernel,
        stride,
        padding,
        dilation,
        out_length);

    cudaDeviceSynchronize();
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("maxpool1d_fp16", &maxpool1d_fp16, "MaxPool1d fp16 (CUDA)");
}
'''

